Rewrite the following GNU C++0x code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to rewrite:
<original_code>
#include<cstdint>
#include<iostream>
#include<vector>

int64_t nb_digits(int64_t n) {
  n = n < 0 ? -n : n;
  int64_t digits = 0;
  while (n) {
    ++digits;
    n /= 10;
  }
  return digits;
}

int64_t ones(int64_t n) {
  int64_t res = 0;
  for (int i = 0; i < n; ++i)
    res = 10*res + 1;
  return res;
}

int64_t aux2(int64_t n) {
  if (n == 0) return 0;
  n = n < 0 ? -n : n;
  int64_t d = nb_digits(n);
  return d + aux2(n-ones(d));
}

int64_t aux(int64_t n, int64_t sign, int64_t acc, int64_t max, std::vector<int> &already_in) {
  if (acc >= max) return max;
  if (n == 0) return acc;
  if (n < 0) { n = -n; sign = -sign; }
  int64_t d = nb_digits(n);
  int64_t ones_d = ones(d);
  int64_t res1 = max, res2 = max;

  if (0 <= already_in[d]*sign && -10 < already_in[d] && already_in[d] < 10) {
    already_in[d] += sign;
    res1 = aux(n-ones_d, sign, acc+d, max, already_in);
    already_in[d] -= sign;
  }
  if (0 <= already_in[1+d]*sign && -10 < already_in[1+d] && already_in[1+d] < 10) {
    already_in[d+1] += sign;
    res2 = aux(n-10*ones_d-1, sign, acc+d+1, res1, already_in);
    already_in[d+1] -= sign;
  }
  return res1 < res2 ? res1 : res2;
}

int main(int argc, char* argv[]) {
  int64_t n;
  std::cin >> n;
  std::vector<int> already_in(20, 0);
  std::cout << aux(n, 1, 0, aux2(n), already_in) << std::endl;
  return 0;
}

</original_code>
